local STATENOCHANGE = {}
local MAXSTATETRANSACTIONSTEPS = 256

local function assertObject(object, expectedKind)
    assert(
        type(object) == "table"
            and object.kind == expectedKind
            and not object.destroyed,
        ("API nay chi dung duoc tren %s con hoat dong"):format(expectedKind)
    )
end

local function copyLinkedValue(value, visited)
    if type(value) ~= "table" then
        return value
    end
    visited = visited or {}
    if visited[value] then
        return nil
    end
    visited[value] = true
    local result = {}
    for key, child in pairs(value) do
        local copiedKey = copyLinkedValue(key, visited)
        if copiedKey ~= nil then
            result[copiedKey] = copyLinkedValue(child, visited)
        end
    end
    visited[value] = nil
    return result
end

local function linkedValuesEqual(left, right, visited)
    if left == right then
        return true
    end
    if type(left) ~= type(right) or type(left) ~= "table" then
        return false
    end
    visited = visited or {}
    if visited[left] == right then
        return true
    end
    visited[left] = right
    for key, value in pairs(left) do
        if not linkedValuesEqual(value, right[key], visited) then
            return false
        end
    end
    for key in pairs(right) do
        if left[key] == nil then
            return false
        end
    end
    return true
end

local function callStateTransform(callback, fallback, ...)
    if type(callback) ~= "function" then
        return fallback
    end
    local arguments = table.pack(...)
    local ok, result = xpcall(function()
        return callback(table.unpack(arguments, 1, arguments.n))
    end, function(message)
        return debug.traceback(tostring(message), 2)
    end)
    if not ok then
        return fallback
    end
    return result
end

local function resolveState(object)
    if type(object) == "table" and object.kind == "State" then
        assertObject(object, "State")
        return object
    end
    if type(object) == "table" and object.kind == "Option" then
        assertObject(object, "Option")
        assert(object.State, "This feature has no state to link")
        return object.State
    end
    error("Provide a State or a feature with a state", 3)
end

local function choosePrimaryOption(state)
    state.primaryOption = nil
    local fallback = nil
    for option in pairs(state.views) do
        if not option.destroyed and option.Instance ~= nil then
            if not fallback then
                fallback = option
            end
            if type(option.userCallback) == "function" then
                state.primaryOption = option
                return
            end
        end
    end
    state.primaryOption = fallback
end

local function syncStateViews(state)
    for option, binding in pairs(state.views) do
        if option.destroyed or option.Instance == nil then
            state.views[option] = nil
        elseif option.controller.SetValue then
            local mappedValue = callStateTransform(
                binding.ToOption,
                state.Value,
                copyLinkedValue(state.Value),
                option,
                state
            )
            option.stateApplying = true
            local ok, problem = xpcall(function()
                option.controller.SetValue(
                    copyLinkedValue(mappedValue),
                    false
                )
            end, function(message)
                return debug.traceback(tostring(message), 2)
            end)
            option.stateApplying = false
            if not ok then
            end
        end
    end
    if state.primaryOption
        and (
            state.primaryOption.destroyed
            or state.primaryOption.Instance == nil
        )
    then
        choosePrimaryOption(state)
    end
end

local function markStateChanged(transaction, state)
    if transaction.changed[state] then
        return
    end
    transaction.changed[state] = true
    table.insert(transaction.order, state)
end

ApiImpl[1] = function(self, value, transaction, sourceOption)
    if self.destroyed then
        return false
    end
    if transaction.steps >= MAXSTATETRANSACTIONSTEPS then
        if not transaction.warned then
            transaction.warned = true
            
            
        end
        return false
    end

    local normalized = callStateTransform(
        self.Normalize,
        value,
        copyLinkedValue(value),
        self
    )
    if normalized == STATENOCHANGE then
        return false
    end

    for group in pairs(self.groups) do
        if not ApiImpl17 then
            syncStateViews(self)
            return false
        end
    end

    if linkedValuesEqual(self.Value, normalized) then
        syncStateViews(self)
        return false
    end

    transaction.steps = transaction.steps + 1
    self.Value = copyLinkedValue(normalized)
    markStateChanged(transaction, self)
    syncStateViews(self)

    for group in pairs(self.groups) do
        ApiImpl18
    end

    for , link in ipairs(self.links) do
        if link.Connected then
            local targetValue = callStateTransform(
                link.Transform,
                self.Value,
                copyLinkedValue(self.Value),
                copyLinkedValue(link.Target.Value),
                self,
                link.Target
            )
            if targetValue ~= STATENOCHANGE then
                ApiImpl1
            end
        end
    end
    return true
end

local function stateUsesPrimaryCallback(state)
    return not state.registered or type(state.Callback) ~= "function"
end

local function runStateTransaction(
    state,
    value,
    fireCallback,
    sourceOption,
    sourceArguments
)
    local transaction = {
        changed = {},
        fireCallback = fireCallback ~= false,
        order = {},
        sourceArguments = sourceArguments,
        sourceOption = sourceOption,
        steps = 0,
        warned = false,
    }
    ApiImpl1

    if transaction.fireCallback then
        for , changedState in ipairs(transaction.order) do
            safeCallback(
                changedState.Callback,
                copyLinkedValue(changedState.Value),
                changedState,
                sourceOption
            )
            local primaryOption = changedState.primaryOption
            if stateUsesPrimaryCallback(changedState)
                and primaryOption
                and not primaryOption.destroyed
                and type(primaryOption.userCallback) == "function"
            then
                if primaryOption == sourceOption
                    and sourceArguments
                then
                    safeCallback(
                        primaryOption.userCallback,
                        table.unpack(
                            sourceArguments,
                            1,
                            sourceArguments.n
                        )
                    )
                else
                    safeCallback(
                        primaryOption.userCallback,
                        primaryOption.controller.GetValue()
                    )
                end
            end
            for , subscriber in ipairs(changedState.subscribers) do
                if subscriber.Connected then
                    safeCallback(
                        subscriber.Callback,
                        copyLinkedValue(changedState.Value),
                        changedState,
                        sourceOption
                    )
                end
            end
        end

        local changedOption = sourceOption
        if not changedOption or changedOption.destroyed then
            for , changedState in ipairs(transaction.order) do
                for option in pairs(changedState.views) do
                    if not option.destroyed and not option.configIgnored then
                        changedOption = option
                        break
                    end
                end
                if changedOption then
                    break
                end
            end
        end
        if changedOption and Runtime.optionChangedHook then
            Runtime.optionChangedHook(changedOption)
        elseif #transaction.order > 0 and Runtime.stateChangedHook then
            Runtime.stateChangedHook(transaction.order[1])
        end
    end
    return #transaction.order > 0
end

local function createStateObject(window, config, registered)
    local state = setmetatable({
        kind = "State",
        destroyed = false,
        configIgnored = config.Save == false or config.Config == false,
        groups = setmetatable({}, { _mode = "k" }),
        links = {},
        registered = registered == true,
        subscribers = {},
        views = setmetatable({}, { mode = "k" }),
        Callback = config.Callback,
        Name = tostring(config.Name or "State"),
        Normalize = config.Normalize,
        Value = copyLinkedValue(config.Default),
        Window = window,
    }, StateMethods)
    window.stateObjects[state] = true
    return state
end

