ApiImpl[13] = function(self)
    assertObject(self, "State")
    local window = self.Window
    local groups = {}
    for group in pairs(self.groups) do
        table.insert(groups, group)
    end
    for , group in ipairs(groups) do
        if not group.destroyed then
            group:Remove(self)
        end
    end
    for , link in ipairs(self.links) do
        link.Connected = false
    end
    for state in pairs(window.stateObjects) do
        for , link in ipairs(state.links) do
            if link.Source == self or link.Target == self then
                link.Connected = false
            end
        end
    end
    for , subscriber in ipairs(self.subscribers) do
        subscriber.Connected = false
    end
    for option in pairs(self.views) do
        option.State = nil
        option.stateBinding = nil
    end
    self.views = {}
    self.links = {}
    self.subscribers = {}
    self.groups = {}
    self.destroyed = true
    window.stateObjects[self] = nil
    if self.registered then
        window.stateByName[self.Name] = nil
        for index, state in ipairs(window.States) do
            if state == self then
                table.remove(window.States, index)
                break
            end
        end
    end
end

ApiImpl[14] = function(self)
    local count = 0
    for member in pairs(self.members) do
        if member.Value == true then
            count = count + 1
        end
    end
    return count
end

ApiImpl[15] = function(self, excludedState)
    local oldestState = nil
    local oldestOrder = math.huge
    for member in pairs(self.members) do
        if member ~= excludedState and member.Value == true then
            local order = self.activationOrder[member] or 0
            if order < oldestOrder then
                oldestOrder = order
                oldestState = member
            end
        end
    end
