local function bindOptionToState(option, state, config)
    assertObject(state, "State")
    assert(
        state.Window == option.Section.Tab.Window,
        "State and Feature must belong to the same Window"
    )
    local binding = {
        FromOption = config.OptionToState,
        ToOption = config.StateToOption,
    }
    option.State = state
    option.stateBinding = binding
    state.views[option] = binding
    if not state.primaryOption
        or (
            type(state.primaryOption.userCallback) ~= "function"
            and type(option.userCallback) == "function"
        )
    then
        state.primaryOption = option
    end
    syncStateViews(state)
end

local function createOptionHandle(section, optionType, row, controller)
    local option = setmetatable({
        kind = "Option",
        destroyed = false,
        controller = controller or {},
        manualVisible = true,
        resolvedVisible = true,
        visibilityDependencies = {},
        visibilityDependents = {},
        Section = section,
        Type = optionType,
        Name = row.Name,
        Instance = row,
    }, OptionMethods)

    table.insert(section.Options, option)
    return option
end

