local function dependencyMatches(dependency)
    local value = ApiImpl2
    if dependency.Predicate then
        local ok, result = pcall(
            dependency.Predicate,
            copyLinkedValue(value),
            dependency.Source,
            dependency.Child
        )
        return ok and result == true
    end
    return linkedValuesEqual(value, dependency.Expected)
end

local function resolvedOptionVisibility(option, seen)
    if option.manualVisible == false then
        return false
    end
    for , dependency in ipairs(option.visibilityDependencies or {}) do
        if dependency.Connected then
            if not dependencyMatches(dependency) then
                return false
            end
            local sourceOption = dependency.SourceOption
            if sourceOption and not sourceOption.destroyed then
                seen = seen or {}
                if not seen[sourceOption] then
                    seen[sourceOption] = true
                    if not resolvedOptionVisibility(sourceOption, seen) then
                        return false
                    end
                end
            end
        end
    end
    return true
end

ApiImpl[43] = function(self)
    
    
    
    
    local hostWidth = #(self.visibilityDependencies or {}) > 0 and 0.96 or 1
    if self.subOfParent then
        hostWidth = 0.9
    end
    self.visibilityHostWidth = hostWidth
    if self.visibilityHost and self.visibilityHost.Parent then
        local oldSize = self.visibilityHost.Size
        self.visibilityHost.Size = UDim2.new(
            hostWidth,
            0,
            oldSize.Y.Scale,
            oldSize.Y.Offset
        )
        return self.visibilityHost
    end

    local row = self.Instance
    local parent = row and row.Parent
    if not row or not parent then
        return row
    end

    local host = Instance.new("Frame")
    host.Name = row.Name .. "CollapsibleContent"
    host.Active = false
    host.BackgroundTransparency = 1
    host.BorderSizePixel = 0
    host.ClipsDescendants = true
    host.LayoutOrder = row.LayoutOrder
    host.Size = UDim2.new(
        hostWidth,
        0,
        0,
        math.max(1, row.AbsoluteSize.Y)
    )
    host.Visible = row.Visible
    host.ZIndex = row.ZIndex
    host.Parent = parent

    row.LayoutOrder = 1
    row.AnchorPoint = Vector2.new(0.5, 0)
    row.Position = UDim2.fromScale(0.5, 0)
    row.Visible = true
    row.Parent = host

    self.visibilityHost = host
    self.visibilityAnimating = false
    self.visibilityHostConnections = self.visibilityHostConnections or {}

    local function syncExpandedHeight()
        if self.destroyed or not host.Parent or not row.Parent then
            return
        end
        local height = math.max(1, row.AbsoluteSize.Y, row.Size.Y.Offset)
        self.visibilityExpandedHeight = height
        if not self.visibilityAnimating and self.resolvedVisible ~= false then
            host.Size = UDim2.new(
                self.visibilityHostWidth or 1,
                0,
                0,
                height
            )
        end
    end
    table.insert(
        self.visibilityHostConnections,
        row:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncExpandedHeight)
    )
    table.insert(
        self.visibilityHostConnections,
        row:GetPropertyChangedSignal("Size"):Connect(syncExpandedHeight)
    )
    syncExpandedHeight()
    return host
end

ApiImpl[44] = function(self, animated)
    assertObject(self, "Option")
    local previous = self.resolvedVisible
    local visible = resolvedOptionVisibility(self)
    self.resolvedVisible = visible

    
    
    
    
    
    
    
    
    if previous ~= visible and not self.cascadingVisibility then
        self.cascadingVisibility = true
        for , dependency in ipairs(self.visibilityDependents or {}) do
            local child = dependency.Child
            if dependency.Connected
                and child
                and not child.destroyed
            then
                ApiImpl44
            end
        end
        self.cascadingVisibility = false
    end

    local host = ApiImpl43
    if not host then
        return self
    end

    
    
    if self.preSearchVisible ~= nil then
        self.preSearchVisible = visible
        host.Visible = self.searchMatched == true and visible
        task.defer(self.Section.refreshHeight)
        return self
    end

    self.visibilityRevision = (self.visibilityRevision or 0) + 1
    local revision = self.visibilityRevision
    local wasAnimating = self.visibilityTween ~= nil
    if self.visibilityTween then
        self.visibilityTween:Cancel()
        self.visibilityTween = nil
    end
    if host.Visible == visible and not wasAnimating then
        return self
    end
    if not visible and self.controller.Close then
        self.controller.Close()
    end

    local row = self.Instance
    local expandedHeight = math.max(
        1,
        self.visibilityExpandedHeight or 0,
        row and row.AbsoluteSize.Y or 0,
        row and row.Size.Y.Offset or 0
    )
    self.visibilityExpandedHeight = expandedHeight
    local targetSize = UDim2.new(
        self.visibilityHostWidth or 1,
        0,
        0,
        visible and expandedHeight or 0
    )

    if visible then
        
        
        host.Visible = true
    end
    if animated == false then
        self.visibilityAnimating = false
        host.Size = targetSize
        host.Visible = visible
        task.defer(self.Section.refreshHeight)
        return self
    end

    self.visibilityAnimating = true
    local info = TweenInfo.new(
        0.28,
        Enum.EasingStyle.Quint,
        Enum.EasingDirection.Out
    )
    self.visibilityTween = TweenService:Create(host, info, {
        Size = targetSize,
    })
    self.visibilityTween.Completed:Connect(function()
        if self.destroyed
            or revision ~= self.visibilityRevision
            or not self.visibilityHost
        then
            return
        end
        self.visibilityTween = nil
        self.visibilityAnimating = false
        host.Visible = visible
        if visible then
            host.Size = UDim2.new(
                self.visibilityHostWidth or 1,
                0,
                0,
                self.visibilityExpandedHeight or expandedHeight
            )
        end
        self.Section.refreshHeight()
        if self.Section.stabilizeLayout then
            self.Section.stabilizeLayout()
        end
    end)
    self.visibilityTween:Play()
    task.defer(self.Section.refreshHeight)
    return self
end

