ApiImpl[85] = function(self)
    assertObject(self, "Option")
    local section = self.Section
    self.destroyed = true

    self.visibilityRevision = (self.visibilityRevision or 0) + 1
    if self.visibilityTween then
        self.visibilityTween:Cancel()
        self.visibilityTween = nil
    end
    for , connection in ipairs(self.visibilityHostConnections or {}) do
        if connection.Connected then
            connection:Disconnect()
        end
    end
    self.visibilityHostConnections = {}
    for , dependency in ipairs(self.visibilityDependencies or {}) do
        dependency.Connected = false
        if dependency.Connection then
            dependency.Connection:Disconnect()
        end
    end
    self.visibilityDependencies = {}
    for , dependency in ipairs(self.visibilityDependents or {}) do
        dependency:Disconnect()
    end
    self.visibilityDependents = {}

    if self.controller.Close then
        self.controller.Close()
    end
    if self.controller.Destroy then
        local ok, problem = pcall(self.controller.Destroy)
        if not ok then
        end
    end

    local state = self.State
    if state then
        state.views[self] = nil
        choosePrimaryOption(state)
        self.State = nil
        self.stateBinding = nil
        if not state.registered
            and next(state.views) == nil
            and not state.destroyed
        then
            ApiImpl13
        end
    end

    section.optionByName[self.Name] = nil
    for index, option in ipairs(section.Options) do
        if option == self then
            table.remove(section.Options, index)
            break
        end
    end
    if self.visibilityHost then
        self.visibilityHost:Destroy()
        self.visibilityHost = nil
        self.Instance = nil
    elseif self.Instance then
        self.Instance:Destroy()
        self.Instance = nil
    end
    self.controller = {}
    if not section.destroyed then
        task.defer(section.refreshHeight)
    end
end

local function bindResponsiveFixedRowHeight(section, row)
    local callback = Protected[1]
    assert(type(callback) == "function", "Protected UI engine is not ready.")
    return callback(section, row)
end

local function addRowToSection(section, optionType, row, controller)
    assertObject(section, "Section")
    section.nextOptionOrder = section.nextOptionOrder + 1
    row.LayoutOrder = section.nextOptionOrder
    row.Parent = section.content
    local cleanupResponsive = bindResponsiveFixedRowHeight(section, row)
    
    
    local rowSizeConnection = row:GetPropertyChangedSignal("AbsoluteSize"):Connect(
        section.refreshHeight
    )
    controller = controller or {}
    local originalDestroy = controller.Destroy
    local controllerDestroyed = false
    controller.Destroy = function()
        if controllerDestroyed then
            return
        end
        controllerDestroyed = true
        if originalDestroy then
            originalDestroy()
        end
        cleanupResponsive()
        if rowSizeConnection.Connected then
            rowSizeConnection:Disconnect()
        end
    end
    task.defer(section.refreshHeight)
    if section.stabilizeLayout then
        section.stabilizeLayout()
    end
    return createOptionHandle(section, optionType, row, controller)
end

