                table.insert(content.Items, entry)
            end
            contentDirty = true
        end

        function controller.SetSearchEnabled(enabled)
            content.SearchEnabled = enabled == true
            contentDirty = true
            layoutDirty = true
        end

        function controller.SetSearchQuery(query)
